def apply_implementation() -> None:
    owner_source = '''using System.Collections.Concurrent;\n\nnamespace LatencyPilot.GpuBenchmark;\n\n/// <summary>\n/// Owns every HWND/D3D12 renderer operation on one dedicated Windows thread.\n/// Async pipe continuations enqueue work here and never touch renderer/window state directly.\n/// </summary>\ninternal sealed class BenchmarkRendererOwner : IAsyncDisposable\n{\n    private static readonly TimeSpan IdlePumpInterval = TimeSpan.FromMilliseconds(15);\n\n    private readonly Func<D3D12BenchmarkRenderer> rendererFactory;\n    private readonly BlockingCollection<Action> workQueue = new();\n    private readonly Thread ownerThread;\n    private readonly TaskCompletionSource initialized = new(TaskCreationOptions.RunContinuationsAsynchronously);\n    private readonly TaskCompletionSource completed = new(TaskCreationOptions.RunContinuationsAsynchronously);\n    private D3D12BenchmarkRenderer? renderer;\n    private Exception? terminalFailure;\n    private int disposeRequested;\n\n    private BenchmarkRendererOwner(Func<D3D12BenchmarkRenderer> rendererFactory)\n    {\n        this.rendererFactory = rendererFactory ?? throw new ArgumentNullException(nameof(rendererFactory));\n        ownerThread = new Thread(ThreadMain)\n        {\n            IsBackground = false,\n            Name = "LatencyPilot GPU benchmark renderer owner",\n        };\n        ownerThread.SetApartmentState(ApartmentState.STA);\n        ownerThread.Start();\n    }\n\n    internal static async Task<BenchmarkRendererOwner> CreateAsync(\n        Func<D3D12BenchmarkRenderer> rendererFactory)\n    {\n        var owner = new BenchmarkRendererOwner(rendererFactory);\n        try\n        {\n            await owner.initialized.Task.ConfigureAwait(false);\n            return owner;\n        }\n        catch\n        {\n            await owner.completed.Task.ConfigureAwait(false);\n            owner.workQueue.Dispose();\n            throw;\n        }\n    }\n\n    internal Task<FrozenBenchmarkWorkload> CalibrateAsync(\n        BenchmarkWorkload benchmark,\n        CancellationToken cancellationToken = default)\n    {\n        ArgumentNullException.ThrowIfNull(benchmark);\n        return InvokeAsync(\n            active => benchmark.CalibrateAsync(active, cancellationToken).GetAwaiter().GetResult(),\n            cancellationToken);\n    }\n\n    internal Task<GpuBenchmarkTrialArtifact> RunTrialAsync(\n        BenchmarkWorkload benchmark,\n        FrozenBenchmarkWorkload workload,\n        TimeSpan duration,\n        CancellationToken cancellationToken = default)\n    {\n        ArgumentNullException.ThrowIfNull(benchmark);\n        ArgumentNullException.ThrowIfNull(workload);\n        return InvokeAsync(\n            active => benchmark.RunTrialAsync(active, workload, duration, cancellationToken).GetAwaiter().GetResult(),\n            cancellationToken);\n    }\n\n    internal Task RecreateRendererAsync(CancellationToken cancellationToken = default) =>\n        InvokeAsync(\n            active =>\n            {\n                var next = rendererFactory();\n                try\n                {\n                    active.Dispose();\n                }\n                catch\n                {\n                    next.Dispose();\n                    throw;\n                }\n\n                renderer = next;\n                return true;\n            },\n            cancellationToken);\n\n    public async ValueTask DisposeAsync()\n    {\n        if (Interlocked.Exchange(ref disposeRequested, 1) == 0)\n        {\n            workQueue.CompleteAdding();\n        }\n\n        await completed.Task.ConfigureAwait(false);\n        workQueue.Dispose();\n    }\n\n    private Task<T> InvokeAsync<T>(\n        Func<D3D12BenchmarkRenderer, T> action,\n        CancellationToken cancellationToken)\n    {\n        ArgumentNullException.ThrowIfNull(action);\n        cancellationToken.ThrowIfCancellationRequested();\n        ObjectDisposedException.ThrowIf(Volatile.Read(ref disposeRequested) != 0, this);\n\n        if (terminalFailure is { } failure)\n        {\n            return Task.FromException<T>(new InvalidOperationException(\n                "The benchmark renderer owner thread is no longer available.",\n                failure));\n        }\n\n        var completion = new TaskCompletionSource<T>(TaskCreationOptions.RunContinuationsAsynchronously);\n        try\n        {\n            workQueue.Add(\n                () =>\n                {\n                    if (cancellationToken.IsCancellationRequested)\n                    {\n                        completion.TrySetCanceled(cancellationToken);\n                        return;\n                    }\n\n                    try\n                    {\n                        var active = renderer\n                            ?? throw new InvalidOperationException("Renderer owner has no active D3D12 renderer.");\n                        completion.TrySetResult(action(active));\n                    }\n                    catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)\n                    {\n                        completion.TrySetCanceled(cancellationToken);\n                    }\n                    catch (Exception exception)\n                    {\n                        completion.TrySetException(exception);\n                    }\n                },\n                cancellationToken);\n        }\n        catch (InvalidOperationException) when (workQueue.IsAddingCompleted)\n        {\n            completion.TrySetException(new ObjectDisposedException(nameof(BenchmarkRendererOwner)));\n        }\n\n        return completion.Task;\n    }\n\n    private void ThreadMain()\n    {\n        Exception? fatal = null;\n        try\n        {\n            renderer = rendererFactory();\n            initialized.TrySetResult();\n\n            while (!workQueue.IsCompleted)\n            {\n                if (workQueue.TryTake(out var action, IdlePumpInterval))\n                {\n                    action();\n                    continue;\n                }\n\n                if (renderer is { } active && !active.PumpMessages())\n                {\n                    throw new OperationCanceledException(\n                        "The benchmark render window was closed on its owner thread.");\n                }\n            }\n        }\n        catch (Exception exception)\n        {\n            fatal = exception;\n            terminalFailure = exception;\n            initialized.TrySetException(exception);\n        }\n        finally\n        {\n            try\n            {\n                renderer?.Dispose();\n            }\n            catch (Exception disposeFailure)\n            {\n                fatal ??= disposeFailure;\n                terminalFailure ??= disposeFailure;\n            }\n            finally\n            {\n                renderer = null;\n            }\n\n            while (workQueue.TryTake(out var pending))\n            {\n                try\n                {\n                    pending();\n                }\n                catch\n                {\n                    // Pending closures own their TaskCompletionSource and fail it themselves.\n                }\n            }\n\n            if (fatal is null)\n            {\n                completed.TrySetResult();\n            }\n            else\n            {\n                // Shutdown remains awaitable without hiding the first renderer failure.\n                completed.TrySetResult();\n            }\n        }\n    }\n}\n'''
    write("src/LatencyPilot.GpuBenchmark/BenchmarkRendererOwner.cs", owner_source)

    window = "src/LatencyPilot.GpuBenchmark/BenchmarkWindow.cs"
    replace_once(window, "    private readonly WindowProc windowProc;\n    private readonly string className;\n", "    private readonly WindowProc windowProc;\n    private readonly string className;\n    private readonly int ownerThreadId;\n")
    replace_once(window, "        Width = width;\n        Height = height;\n", "        Width = width;\n        Height = height;\n        ownerThreadId = Environment.CurrentManagedThreadId;\n")
    replace_once(window, "    internal bool PumpMessages()\n    {\n        while", "    internal bool PumpMessages()\n    {\n        EnsureOwnerThread();\n        while")
    replace_once(window, "    public void Dispose()\n    {\n        if (disposed) return;\n        disposed = true;\n        if (Handle != IntPtr.Zero) DestroyWindow(Handle);\n        UnregisterClassW(className, GetModuleHandleW(null));\n        GC.KeepAlive(windowProc);\n    }\n", '''    public void Dispose()\n    {\n        EnsureOwnerThread();\n        if (disposed) return;\n        disposed = true;\n\n        Exception? destroyFailure = null;\n        if (Handle != IntPtr.Zero && IsWindow(Handle) && !DestroyWindow(Handle))\n        {\n            destroyFailure = new Win32Exception(\n                Marshal.GetLastPInvokeError(),\n                "DestroyWindow failed on the benchmark-window owner thread.");\n        }\n\n        UnregisterClassW(className, GetModuleHandleW(null));\n        GC.KeepAlive(windowProc);\n        if (destroyFailure is not null)\n        {\n            throw destroyFailure;\n        }\n    }\n\n    private void EnsureOwnerThread()\n    {\n        if (Environment.CurrentManagedThreadId != ownerThreadId)\n        {\n            throw new InvalidOperationException(\n                $"BenchmarkWindow belongs to managed thread {ownerThreadId}, but thread {Environment.CurrentManagedThreadId} attempted a Win32 window operation.");\n        }\n    }\n''')

    renderer = "src/LatencyPilot.GpuBenchmark/D3D12BenchmarkRenderer.cs"
    replace_once(renderer, "    internal IReadOnlyList<ulong> CaptureWorkerChecksums() =>\n        workers.Select(static worker => worker.SimulationChecksum).ToArray();\n", "    internal bool PumpMessages()\n    {\n        ObjectDisposedException.ThrowIf(disposed, this);\n        return window.PumpMessages();\n    }\n\n    internal IReadOnlyList<ulong> CaptureWorkerChecksums() =>\n        workers.Select(static worker => worker.SimulationChecksum).ToArray();\n")

    program = '''using System.Text;\nusing System.Text.Json;\nusing LatencyPilot.GpuBenchmark;\nusing LatencyPilot.Platform.Windows.System;\n\nBenchmarkOptions options;\ntry\n{\n    options = BenchmarkOptions.Parse(args);\n}\ncatch (Exception exception) when (exception is ArgumentException or NotSupportedException)\n{\n    Console.Error.WriteLine(exception.Message);\n    return 2;\n}\n\ntry\n{\n    var topology = ProcessorTopologyReader.Capture();\n    if (topology.ProcessorGroupCount != 1)\n    {\n        throw new NotSupportedException("gpu-affinity-benchmark-v1 currently requires exactly one Windows processor group.");\n    }\n    if (options.WorkerCount > topology.PhysicalCoreCount)\n    {\n        throw new InvalidOperationException(\n            $"Requested {options.WorkerCount} workers but Windows reports only {topology.PhysicalCoreCount} physical cores.");\n    }\n\n    var workerMap = topology.Cores.Take(options.WorkerCount)\n        .Select(static core => core.LogicalProcessors\n            .OrderBy(static processor => processor.Group)\n            .ThenBy(static processor => processor.Number)\n            .First())\n        .ToArray();\n\n    BenchmarkProtocol.WriteProgress(\n        Console.Out,\n        options.SessionId,\n        "initializing",\n        0d,\n        $"Initializing D3D12 benchmark at {options.Width}x{options.Height} with {workerMap.Length} physical-core workers.");\n\n    var benchmark = new BenchmarkWorkload(options, Console.Out, workerMap);\n    await using var rendererOwner = await BenchmarkRendererOwner.CreateAsync(\n        () => new D3D12BenchmarkRenderer(options.Width, options.Height, workerMap, options.Seed));\n    var frozen = await rendererOwner.CalibrateAsync(benchmark);\n    BenchmarkProtocol.WriteProgress(\n        Console.Out,\n        options.SessionId,\n        "calibrated",\n        0d,\n        $"Frozen workload: {frozen.CommandBatchesPerWorker} command batches and {frozen.SimulationIterationsPerWorker} simulation iterations per worker.");\n\n    if (options.IsControlledSession)\n    {\n        BenchmarkProtocol.WriteProgress(\n            Console.Out,\n            options.SessionId,\n            "waiting-control",\n            0d,\n            "Frozen benchmark session is waiting for the authenticated Gate A controller.");\n        var server = new BenchmarkControlServer(\n            options,\n            benchmark,\n            rendererOwner,\n            frozen);\n        await server.RunAsync();\n        BenchmarkProtocol.WriteProgress(\n            Console.Out,\n            options.SessionId,\n            "complete",\n            1d,\n            "Controlled benchmark session completed without recalibrating the workload.");\n        return 0;\n    }\n\n    var outputPath = options.OutputPath\n        ?? throw new InvalidOperationException("Single-trial benchmark output path is missing.");\n    Directory.CreateDirectory(Path.GetDirectoryName(outputPath)!);\n    var artifact = await rendererOwner.RunTrialAsync(benchmark, frozen, options.Duration);\n    var jsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web) { WriteIndented = true };\n    File.WriteAllText(outputPath, JsonSerializer.Serialize(artifact, jsonOptions), new UTF8Encoding(false));\n    BenchmarkProtocol.WriteProgress(Console.Out, options.SessionId, "complete", 1d, $"Benchmark artifact written to {outputPath}.");\n    return 0;\n}\ncatch (OperationCanceledException exception)\n{\n    BenchmarkProtocol.WriteFailure(Console.Out, options.SessionId, "cancelled", exception.Message);\n    return 3;\n}\ncatch (Exception exception)\n{\n    BenchmarkProtocol.WriteFailure(Console.Out, options.SessionId, "failed", exception.Message);\n    return 1;\n}\n'''
    write("src/LatencyPilot.GpuBenchmark/Program.cs", program)

    server = '''using System.IO.Pipes;\nusing System.Security.AccessControl;\nusing System.Security.Principal;\nusing System.Text;\nusing System.Text.Json;\nusing LatencyPilot.Core.Benchmarking;\n\nnamespace LatencyPilot.GpuBenchmark;\n\ninternal sealed class BenchmarkControlServer(\n    BenchmarkOptions options,\n    BenchmarkWorkload benchmark,\n    BenchmarkRendererOwner rendererOwner,\n    FrozenBenchmarkWorkload frozenWorkload)\n{\n    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);\n    private readonly HashSet<int> completedRuns = [];\n\n    internal async Task RunAsync(CancellationToken cancellationToken = default)\n    {\n        if (!options.IsControlledSession ||\n            options.ControlPipeName is not { Length: > 0 } pipeName ||\n            options.ControlToken is not { Length: > 0 } token ||\n            options.OutputDirectory is not { Length: > 0 } outputDirectory)\n        {\n            throw new InvalidOperationException("Benchmark control server requires controlled-session options.");\n        }\n\n        ArgumentNullException.ThrowIfNull(rendererOwner);\n        Directory.CreateDirectory(outputDirectory);\n        using var pipe = CreatePipe(pipeName);\n        await pipe.WaitForConnectionAsync(cancellationToken).ConfigureAwait(false);\n        using var reader = new StreamReader(\n            pipe, new UTF8Encoding(false), detectEncodingFromByteOrderMarks: false, bufferSize: 4096, leaveOpen: true);\n        using var writer = new StreamWriter(\n            pipe, new UTF8Encoding(false), bufferSize: 4096, leaveOpen: true)\n        {\n            AutoFlush = true,\n        };\n\n        await WriteResponseAsync(\n            writer,\n            new GpuBenchmarkControlResponse(\n                GpuBenchmarkControlResponse.SchemaId, options.SessionId, GpuBenchmarkControlResponseStatus.Ready,\n                0, checked((uint)Environment.ProcessId), null,\n                "Benchmark calibrated once; frozen workload is ready for controlled trials."),\n            cancellationToken).ConfigureAwait(false);\n\n        while (true)\n        {\n            cancellationToken.ThrowIfCancellationRequested();\n            var line = await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false);\n            if (line is null)\n            {\n                throw new IOException("Benchmark control client disconnected before sending Stop.");\n            }\n\n            GpuBenchmarkControlCommand? command;\n            try\n            {\n                command = JsonSerializer.Deserialize<GpuBenchmarkControlCommand>(line, JsonOptions);\n            }\n            catch (JsonException exception)\n            {\n                await WriteRejectedAsync(writer, 0, $"Invalid benchmark control JSON: {exception.Message}", cancellationToken)\n                    .ConfigureAwait(false);\n                continue;\n            }\n\n            if (!GpuBenchmarkControlProtocol.TryValidate(command, options.SessionId, token, out var rejection))\n            {\n                await WriteRejectedAsync(writer, command?.RunNumber ?? 0, rejection!, cancellationToken)\n                    .ConfigureAwait(false);\n                continue;\n            }\n\n            if (command!.Kind == GpuBenchmarkControlCommandKind.Stop)\n            {\n                await WriteResponseAsync(\n                    writer,\n                    new GpuBenchmarkControlResponse(\n                        GpuBenchmarkControlResponse.SchemaId, options.SessionId, GpuBenchmarkControlResponseStatus.Stopped,\n                        0, checked((uint)Environment.ProcessId), null,\n                        "Controlled benchmark session stopped cleanly."),\n                    cancellationToken).ConfigureAwait(false);\n                return;\n            }\n\n            if (command.Kind == GpuBenchmarkControlCommandKind.RecreateRenderer)\n            {\n                try\n                {\n                    await RecreateRendererWithRetryAsync(rendererOwner, cancellationToken).ConfigureAwait(false);\n                    await WriteResponseAsync(\n                        writer,\n                        new GpuBenchmarkControlResponse(\n                            GpuBenchmarkControlResponse.SchemaId, options.SessionId, GpuBenchmarkControlResponseStatus.RendererReady,\n                            0, checked((uint)Environment.ProcessId), null,\n                            "D3D12 renderer recreated on its owner thread after the GPU configuration change."),\n                        cancellationToken).ConfigureAwait(false);\n                }\n                catch (Exception exception) when (\n                    exception is not OperationCanceledException || !cancellationToken.IsCancellationRequested)\n                {\n                    await WriteResponseAsync(\n                        writer,\n                        new GpuBenchmarkControlResponse(\n                            GpuBenchmarkControlResponse.SchemaId, options.SessionId, GpuBenchmarkControlResponseStatus.Failed,\n                            0, checked((uint)Environment.ProcessId), null,\n                            $"Benchmark renderer recreation failed: {exception.GetType().Name}: {exception.Message}"),\n                        cancellationToken).ConfigureAwait(false);\n                }\n\n                continue;\n            }\n\n            if (!completedRuns.Add(command.RunNumber))\n            {\n                await WriteRejectedAsync(\n                    writer, command.RunNumber,\n                    "Benchmark trial run number was already completed in this session.", cancellationToken).ConfigureAwait(false);\n                continue;\n            }\n\n            var artifactPath = Path.Combine(\n                outputDirectory, $"gpu-benchmark-{options.SessionId:N}-trial-{command.RunNumber:D4}.json");\n            if (File.Exists(artifactPath))\n            {\n                completedRuns.Remove(command.RunNumber);\n                await WriteRejectedAsync(\n                    writer, command.RunNumber,\n                    "Benchmark trial artifact already exists; refusing to overwrite evidence.", cancellationToken).ConfigureAwait(false);\n                continue;\n            }\n\n            try\n            {\n                // Warm-up and score reuse one renderer, but every renderer/window call\n                // is marshalled onto BenchmarkRendererOwner's fixed thread.\n                var artifact = await rendererOwner.RunTrialAsync(\n                    benchmark,\n                    frozenWorkload,\n                    TimeSpan.FromMilliseconds(command.DurationMilliseconds),\n                    cancellationToken).ConfigureAwait(false);\n                await File.WriteAllTextAsync(\n                    artifactPath, JsonSerializer.Serialize(artifact, JsonOptions),\n                    new UTF8Encoding(false), cancellationToken).ConfigureAwait(false);\n                await WriteResponseAsync(\n                    writer,\n                    new GpuBenchmarkControlResponse(\n                        GpuBenchmarkControlResponse.SchemaId, options.SessionId, GpuBenchmarkControlResponseStatus.TrialCompleted,\n                        command.RunNumber, checked((uint)Environment.ProcessId), artifactPath,\n                        "Frozen benchmark trial completed."),\n                    cancellationToken).ConfigureAwait(false);\n            }\n            catch (Exception exception) when (\n                exception is not OperationCanceledException || !cancellationToken.IsCancellationRequested)\n            {\n                completedRuns.Remove(command.RunNumber);\n                await WriteResponseAsync(\n                    writer,\n                    new GpuBenchmarkControlResponse(\n                        GpuBenchmarkControlResponse.SchemaId, options.SessionId, GpuBenchmarkControlResponseStatus.Failed,\n                        command.RunNumber, checked((uint)Environment.ProcessId), null,\n                        $"Benchmark trial failed: {exception.GetType().Name}: {exception.Message}"),\n                    cancellationToken).ConfigureAwait(false);\n            }\n        }\n    }\n\n    private static async Task RecreateRendererWithRetryAsync(\n        BenchmarkRendererOwner rendererOwner,\n        CancellationToken cancellationToken)\n    {\n        var deadline = TimeSpan.FromSeconds(30);\n        var started = DateTimeOffset.UtcNow;\n        var delay = TimeSpan.FromMilliseconds(500);\n        Exception? lastFailure = null;\n        while (DateTimeOffset.UtcNow - started < deadline)\n        {\n            cancellationToken.ThrowIfCancellationRequested();\n            try\n            {\n                await rendererOwner.RecreateRendererAsync(cancellationToken).ConfigureAwait(false);\n                return;\n            }\n            catch (Exception exception) when (exception is\n                InvalidOperationException or\n                PlatformNotSupportedException or\n                System.ComponentModel.Win32Exception or\n                SharpGen.Runtime.SharpGenException)\n            {\n                lastFailure = exception;\n                await Task.Delay(delay, cancellationToken).ConfigureAwait(false);\n                delay = TimeSpan.FromMilliseconds(Math.Min(delay.TotalMilliseconds * 2d, 4000d));\n            }\n        }\n\n        throw new InvalidOperationException(\n            "D3D12 benchmark device recreation failed after the GPU configuration-change restart; the display adapter did not return in time.",\n            lastFailure);\n    }\n\n    private static NamedPipeServerStream CreatePipe(string pipeName)\n    {\n        if (!OperatingSystem.IsWindows())\n        {\n            throw new PlatformNotSupportedException("Controlled GPU benchmark sessions require Windows named-pipe ACLs.");\n        }\n\n        using var identity = WindowsIdentity.GetCurrent(TokenAccessLevels.Query);\n        var userSid = identity.User\n            ?? throw new InvalidOperationException("The benchmark process has no Windows user SID.");\n        var security = new PipeSecurity();\n        security.SetOwner(userSid);\n        security.SetAccessRuleProtection(isProtected: true, preserveInheritance: false);\n        security.AddAccessRule(new PipeAccessRule(\n            userSid, PipeAccessRights.FullControl, AccessControlType.Allow));\n\n        return NamedPipeServerStreamAcl.Create(\n            pipeName, PipeDirection.InOut, maxNumberOfServerInstances: 1,\n            PipeTransmissionMode.Byte, PipeOptions.Asynchronous,\n            inBufferSize: 4096, outBufferSize: 4096, security);\n    }\n\n    private Task WriteRejectedAsync(\n        TextWriter writer, int runNumber, string message, CancellationToken cancellationToken) =>\n        WriteResponseAsync(\n            writer,\n            new GpuBenchmarkControlResponse(\n                GpuBenchmarkControlResponse.SchemaId, options.SessionId, GpuBenchmarkControlResponseStatus.Rejected,\n                runNumber, checked((uint)Environment.ProcessId), null, message),\n            cancellationToken);\n\n    private static async Task WriteResponseAsync(\n        TextWriter writer,\n        GpuBenchmarkControlResponse response,\n        CancellationToken cancellationToken)\n    {\n        var json = JsonSerializer.Serialize(response, JsonOptions);\n        await writer.WriteLineAsync(json.AsMemory(), cancellationToken).ConfigureAwait(false);\n        await writer.FlushAsync(cancellationToken).ConfigureAwait(false);\n    }\n}\n'''
    write("src/LatencyPilot.GpuBenchmark/BenchmarkControlServer.cs", server)


if __name__ == "__main__":
    if len(sys.argv) != 2 or sys.argv[1] not in {"tests", "implementation"}:
        raise SystemExit("usage: audit-closure-f1-thread.py tests|implementation")
    if sys.argv[1] == "tests":
        apply_tests()
    else:
        apply_implementation()
